/*
 * A162531  Numbers k whose largest divisor <= sqrt(k) is 11.
 * https://oeis.org/A162531
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   Numbers k whose largest divisor <= sqrt(k) is 11. The sequence
 *            is generated by scanning multiples of 11 and testing each
 *            candidate
 * Range:     u8 none, u16 n <= 172, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/floor_sqrt.h"

static inline bool is_valid_k(seq_t k)
{
    /* 1. 11 must divide k. */
    if (k % (seq_t)11 != 0) return false;

    /* 2. sqrt(k) must be at least 11. */
    seq_t sqrt_k = floor_sqrt(k);
    if (sqrt_k < (seq_t)11) return false;

    /* 3. Let m = k / 11.  All divisors of k are d0 and 11*d0 where d0 | m. */
    idx_t m = (idx_t)(k / (seq_t)11);
    idx_t sqrt_k_idx = (idx_t)sqrt_k;

    /* 3a. Divisor m itself must not lie between 12 and sqrt(k). */
    if (m <= sqrt_k_idx && m > (idx_t)11) return false;

    /* 3b. Check all divisor pairs of m. */
    for (idx_t d = 2; d * d <= m; ++d) {
        if (m % d != 0) continue;
        idx_t e = m / d;            /* complementary divisor */

        /* Check divisor d (<= sqrt(m)). */
        if (d <= sqrt_k_idx) {
            if (d > 11) return false;                     /* >11 divisor <= sqrt(k) */
            if ((seq_t)11 * d <= sqrt_k) return false;    /* 11*d <= sqrt(k) gives divisor >11 <= sqrt(k) */
        }

        /* Check complementary divisor e. */
        if (e <= sqrt_k_idx) {
            if (e > 11) return false;                     /* >11 divisor <= sqrt(k) */
            if ((seq_t)11 * e <= sqrt_k) return false;    /* 11*e <= sqrt(k) gives divisor >11 <= sqrt(k) */
        }
    }
    return true;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* offset is 1, return 0 for n==0 just in case */
    idx_t count = 0;
    for (idx_t m = 11; /* m grows forever */ ; ++m) {
        seq_t k = (seq_t)11 * (seq_t)m;
        if (is_valid_k(k)) {
            ++count;
            if (count == n) return k;
        }
    }
}
